#include <string>

// How many of the eight tiles around (x, y) equal wanted.
int countAround(const std::string& tiles, int width, int x, int y, char wanted)
{
    const int height{ static_cast<int>(tiles.size()) / width };
    int count{ 0 };
    for (int dy{ -1 }; dy <= 1; ++dy)
    {
        for (int dx{ -1 }; dx <= 1; ++dx)
        {
            if (dx == 0 && dy == 0) continue;
            const int nx{ x + dx };
            const int ny{ y + dy };
            if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
            if (tiles[static_cast<std::size_t>(ny * width + nx)] == wanted) ++count;
        }
    }
    return count;
}

unitTests:
const std::string cross{ "#.#...#.#" };
TEST("the middle") { CHECK_EQ(countAround(cross, 3, 1, 1, '#'), 4); CHECK_EQ(countAround(cross, 3, 1, 1, '.'), 4); }
TEST("a corner has only three neighbours") { CHECK_EQ(countAround(cross, 3, 0, 0, '.'), 3); CHECK_EQ(countAround(cross, 3, 0, 0, '#'), 0); }
TEST("an edge has five neighbours") { CHECK_EQ(countAround(cross, 3, 1, 0, '#'), 2); CHECK_EQ(countAround(cross, 3, 1, 0, '.'), 3); }
TEST("the tile itself does not count") { CHECK_EQ(countAround(std::string(9, 'x'), 3, 1, 1, 'x'), 8); }
TEST("the right edge does not wrap into the next row")
{
    // width 4: "...#" then "#..."; the '#' at the start of row 1 is not next to (3, 0)'s right side.
    CHECK_EQ(countAround("...##...", 4, 3, 0, '#'), 0);
    CHECK_EQ(countAround("...##...", 4, 2, 0, '#'), 1);
    CHECK_EQ(countAround("...##...", 4, 0, 1, '#'), 0);
}
TEST("a wide, short map") { CHECK_EQ(countAround("abcdefgh", 8, 7, 0, 'g'), 1); }

